// backend/src/services/guidance.js
// ---------------------------------------------------------------------------
// Guideline-based next steps for the condition with the highest screening
// score: which tests confirm or exclude it, and the management principles.
//
// The content is a curated, versioned knowledge base (knowledge/
// clinicalGuidance.json) written from published guidance by WHO, the
// Thalassaemia International Federation, NICE and the European LeukemiaNet;
// every item cites its source. It is deliberately NOT generated by a language
// model at request time: a fixed, citable text can be reviewed and signed off
// by a haematology lead, and it cannot invent a recommendation.
//
// frontend/src/lib/clinicalGuidance.json is a byte-identical copy for the mock
// API (test/unit/guidance.test.js checks that).
// ---------------------------------------------------------------------------
const guidance = require('../knowledge/clinicalGuidance.json');
const { CLASSES } = require('../contract');

/** Source records for a list of source ids, in first-use order, de-duplicated. */
function sourcesFor(ids) {
  return [...new Set(ids)].filter((id) => guidance.sources[id]).map((id) => ({ id, ...guidance.sources[id] }));
}

/** Full guidance for one condition, with its sources resolved; null for an unknown condition. */
function forCondition(condition) {
  const entry = guidance.conditions[condition];
  if (!entry) return null;
  const ids = [...entry.confirmatoryTests, ...entry.management].flatMap((item) => item.sources || []);
  return {
    condition,
    version: guidance.version,
    disclaimer: guidance.disclaimer,
    reviewNote: guidance.reviewNote,
    ...entry,
    sources: sourcesFor(ids),
  };
}

/** The same guidance, as returned inside a prediction response (keyed to the top score). */
function summaryFor(condition) {
  return forCondition(condition);
}

const conditions = () => CLASSES.filter((c) => guidance.conditions[c]);

module.exports = { forCondition, summaryFor, conditions, guidance };
